'use strict';
const D=window.DOSUL_DATA,S=D.skills,E=DosulGraph.buildGraph(D),Q=DosulSequence,$=s=>document.querySelector(s),byId=id=>S.find(s=>s.id===id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STYLE_COLORS={절명:'#7051b7',연타:'#b95740',강타:'#80651d',척살:'#526c61',저격:'#33712f',주술:'#a32b3a',파멸:'#872e87',강인:'#16717c',기동:'#306c9c',헌신:'#a12c79',기만:'#52618b',제압:'#8a6328'};
function styleBadge(s){return `<span class="style-badge" style="--style-color:${STYLE_COLORS[s.family]}" title="강화 스타일: ${esc(s.family)}">${esc(s.family)}</span>`;}
